DO $owner_preflight$ DECLARE owner_oid OID; owner_has_external_grant BOOLEAN; BEGIN SELECT oid INTO owner_oid FROM pg_roles WHERE rolname = 'star_scm_repository_owner'; IF owner_oid IS NULL THEN RETURN; END IF; IF EXISTS (SELECT 1 FROM pg_auth_members WHERE member = owner_oid) THEN RAISE EXCEPTION 'star_scm_repository_owner must not inherit or assume another role'; END IF; IF EXISTS (SELECT 1 FROM pg_shdepend WHERE refclassid = 'pg_authid'::regclass AND refobjid = owner_oid AND deptype = 'o') THEN RAISE EXCEPTION 'star_scm_repository_owner must not own database objects'; END IF; IF EXISTS (SELECT 1 FROM pg_shdepend WHERE refclassid = 'pg_authid'::regclass AND refobjid = owner_oid AND deptype = 'a' AND dbid <> 0 AND dbid <> (SELECT oid FROM pg_database WHERE datname = current_database())) THEN RAISE EXCEPTION 'star_scm_repository_owner has direct privileges on objects in another database'; END IF; IF EXISTS (SELECT 1 FROM (SELECT 1 FROM pg_database d CROSS JOIN LATERAL aclexplode(d.datacl) a WHERE d.datacl IS NOT NULL AND a.grantee = owner_oid UNION ALL SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(n.nspacl) a WHERE n.nspname <> 'scm' AND n.nspacl IS NOT NULL AND a.grantee = owner_oid UNION ALL SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE n.nspname <> 'scm' AND c.relacl IS NOT NULL AND a.grantee = owner_oid UNION ALL SELECT 1 FROM pg_attribute at JOIN pg_class c ON c.oid = at.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace CROSS JOIN LATERAL aclexplode(at.attacl) a WHERE n.nspname <> 'scm' AND at.attnum > 0 AND NOT at.attisdropped AND at.attacl IS NOT NULL AND a.grantee = owner_oid UNION ALL SELECT 1 FROM pg_proc f JOIN pg_namespace n ON n.oid = f.pronamespace CROSS JOIN LATERAL aclexplode(f.proacl) a WHERE n.nspname <> 'scm' AND f.proacl IS NOT NULL AND a.grantee = owner_oid UNION ALL SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace CROSS JOIN LATERAL aclexplode(t.typacl) a WHERE n.nspname <> 'scm' AND t.typacl IS NOT NULL AND a.grantee = owner_oid UNION ALL SELECT 1 FROM pg_language l CROSS JOIN LATERAL aclexplode(l.lanacl) a WHERE l.lanacl IS NOT NULL AND a.grantee = owner_oid UNION ALL SELECT 1 FROM pg_tablespace t CROSS JOIN LATERAL aclexplode(t.spcacl) a WHERE t.spcacl IS NOT NULL AND a.grantee = owner_oid UNION ALL SELECT 1 FROM pg_foreign_data_wrapper f CROSS JOIN LATERAL aclexplode(f.fdwacl) a WHERE f.fdwacl IS NOT NULL AND a.grantee = owner_oid UNION ALL SELECT 1 FROM pg_foreign_server s CROSS JOIN LATERAL aclexplode(s.srvacl) a WHERE s.srvacl IS NOT NULL AND a.grantee = owner_oid UNION ALL SELECT 1 FROM pg_largeobject_metadata l CROSS JOIN LATERAL aclexplode(l.lomacl) a WHERE l.lomacl IS NOT NULL AND a.grantee = owner_oid UNION ALL SELECT 1 FROM pg_default_acl d CROSS JOIN LATERAL aclexplode(d.defaclacl) a LEFT JOIN pg_namespace n ON n.oid = d.defaclnamespace WHERE d.defaclacl IS NOT NULL AND a.grantee = owner_oid AND n.nspname IS DISTINCT FROM 'scm') non_scm_grant) THEN RAISE EXCEPTION 'star_scm_repository_owner has direct privileges outside the SCM schema'; END IF; IF to_regclass('pg_catalog.pg_parameter_acl') IS NOT NULL THEN EXECUTE 'SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_parameter_acl p CROSS JOIN LATERAL pg_catalog.aclexplode(p.paracl) a WHERE p.paracl IS NOT NULL AND a.grantee = $1)' INTO owner_has_external_grant USING owner_oid; IF owner_has_external_grant THEN RAISE EXCEPTION 'star_scm_repository_owner has direct parameter privileges'; END IF; END IF; END $owner_preflight$;
CREATE SCHEMA IF NOT EXISTS scm;
DO $role$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'star_scm_repository_owner') THEN EXECUTE 'ALTER ROLE star_scm_repository_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT'; ELSE EXECUTE 'CREATE ROLE star_scm_repository_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT'; END IF; END $role$;
