CREATE TABLE IF NOT EXISTS scm.repository_master (tenant_id UUID NOT NULL CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'), repository_id UUID NOT NULL CHECK (repository_id <> '00000000-0000-0000-0000-000000000000'), version INTEGER NOT NULL CHECK (version > 0), name TEXT NOT NULL CHECK (octet_length(name) BETWEEN 1 AND 255 AND name = btrim(name) AND name !~ '[[:cntrl:]]'), provider_key TEXT CHECK (provider_key IS NULL OR provider_key ~ '^[a-z0-9._-]{1,64}$'), remote_identity TEXT CHECK (remote_identity IS NULL OR (octet_length(remote_identity) BETWEEN 1 AND 512 AND remote_identity = btrim(remote_identity) AND remote_identity !~ '[[:cntrl:][:space:]]' AND provider_key IS NOT NULL)), remote_url TEXT CHECK (remote_url IS NULL OR (octet_length(remote_url) BETWEEN 1 AND 2048 AND remote_url ~* '^(https?://|ssh://)[^/@?#%[:space:]]+/.+$' AND remote_url !~ '[?#%[:space:][:cntrl:]]' AND remote_url !~* '://[^/]+/+$' AND position(chr(92) IN remote_url) = 0)), default_branch TEXT CHECK (default_branch IS NULL OR (octet_length(default_branch) BETWEEN 1 AND 255 AND default_branch = btrim(default_branch) AND default_branch !~ '[[:cntrl:]]')), created_by_actor_id UUID NOT NULL CHECK (created_by_actor_id <> '00000000-0000-0000-0000-000000000000'), changed_by_actor_id UUID NOT NULL CHECK (changed_by_actor_id <> '00000000-0000-0000-0000-000000000000'), valid_from TIMESTAMPTZ NOT NULL DEFAULT transaction_timestamp(), valid_to TIMESTAMPTZ, PRIMARY KEY (tenant_id, repository_id, version), CHECK (valid_to IS NULL OR valid_to >= valid_from));
CREATE UNIQUE INDEX IF NOT EXISTS uq_repository_master_current ON scm.repository_master (tenant_id, repository_id) WHERE valid_to IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_repository_master_provider_identity_current ON scm.repository_master (tenant_id, provider_key, remote_identity) WHERE valid_to IS NULL AND provider_key IS NOT NULL AND remote_identity IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_repository_master_tenant_name_current ON scm.repository_master (tenant_id, name, repository_id) WHERE valid_to IS NULL;
DO $repository_master_current_preflight$ BEGIN IF EXISTS (SELECT 1 FROM scm.repository_master GROUP BY tenant_id, repository_id HAVING count(*) FILTER (WHERE valid_to IS NULL) <> 1) THEN RAISE EXCEPTION 'SCM Repository master history must have exactly one current revision'; END IF; END $repository_master_current_preflight$;
CREATE TABLE IF NOT EXISTS scm.repository_master_event (event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL CHECK (tenant_id <> '00000000-0000-0000-0000-000000000000'), repository_id UUID NOT NULL CHECK (repository_id <> '00000000-0000-0000-0000-000000000000'), repository_version INTEGER NOT NULL CHECK (repository_version > 0), action TEXT NOT NULL CHECK (action IN ('created', 'revised')), actor_id UUID NOT NULL CHECK (actor_id <> '00000000-0000-0000-0000-000000000000'), correlation_id UUID NOT NULL CHECK (correlation_id <> '00000000-0000-0000-0000-000000000000'), occurred_at TIMESTAMPTZ NOT NULL DEFAULT transaction_timestamp(), after_state JSONB NOT NULL CHECK (jsonb_typeof(after_state) = 'object' AND octet_length(after_state::text) <= 8192), FOREIGN KEY (tenant_id, repository_id, repository_version) REFERENCES scm.repository_master (tenant_id, repository_id, version) ON DELETE RESTRICT, UNIQUE (tenant_id, repository_id, repository_version));
CREATE OR REPLACE FUNCTION scm.guard_repository_master_revision() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, scm AS $function$ DECLARE current_tenant UUID; current_actor UUID; previous_version INTEGER; previous_valid_to TIMESTAMPTZ; previous_creator UUID; BEGIN IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'SCM Repository master history cannot be physically deleted'; END IF; current_tenant := NULLIF(current_setting('app.tenant_id', true), '')::UUID; current_actor := NULLIF(current_setting('app.actor_id', true), '')::UUID; IF current_tenant IS NULL OR current_actor IS NULL OR current_tenant = '00000000-0000-0000-0000-000000000000' OR current_actor = '00000000-0000-0000-0000-000000000000' OR NEW.tenant_id <> current_tenant THEN RAISE EXCEPTION 'SCM Repository master write requires matching tenant and actor context'; END IF; IF TG_OP = 'INSERT' THEN IF NEW.changed_by_actor_id <> current_actor OR NEW.valid_to IS NOT NULL OR NEW.valid_from > transaction_timestamp() THEN RAISE EXCEPTION 'SCM Repository master revisions must start current'; END IF; SELECT version, valid_to, created_by_actor_id INTO previous_version, previous_valid_to, previous_creator FROM scm.repository_master WHERE tenant_id = NEW.tenant_id AND repository_id = NEW.repository_id ORDER BY version DESC LIMIT 1 FOR UPDATE; IF NOT FOUND THEN IF NEW.version <> 1 OR NEW.created_by_actor_id <> current_actor THEN RAISE EXCEPTION 'SCM Repository master identity must start at revision one'; END IF; ELSIF NEW.version <> previous_version + 1 OR previous_valid_to IS DISTINCT FROM NEW.valid_from OR NEW.created_by_actor_id <> previous_creator THEN RAISE EXCEPTION 'SCM Repository master revision is not a continuous immutable history'; END IF; ELSE IF OLD.valid_to IS NOT NULL OR NEW.valid_to IS NULL OR NEW.valid_to <> transaction_timestamp() OR (to_jsonb(OLD) - 'valid_to') IS DISTINCT FROM (to_jsonb(NEW) - 'valid_to') THEN RAISE EXCEPTION 'SCM Repository master revisions may only be closed once'; END IF; END IF; RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION scm.assert_repository_master_current_revision() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, scm AS $function$ BEGIN IF NOT EXISTS (SELECT 1 FROM scm.repository_master WHERE tenant_id = NEW.tenant_id AND repository_id = NEW.repository_id AND valid_to IS NULL) THEN RAISE EXCEPTION 'SCM Repository master identity must retain a current revision at transaction commit'; END IF; RETURN NULL; END $function$;
CREATE OR REPLACE FUNCTION scm.audit_repository_master_revision() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, scm AS $function$ DECLARE current_actor UUID; current_correlation UUID; BEGIN current_actor := NULLIF(current_setting('app.actor_id', true), '')::UUID; current_correlation := NULLIF(current_setting('app.correlation_id', true), '')::UUID; IF current_actor IS NULL OR current_correlation IS NULL OR current_actor <> NEW.changed_by_actor_id OR current_correlation = '00000000-0000-0000-0000-000000000000' THEN RAISE EXCEPTION 'SCM Repository master audit requires actor and correlation context'; END IF; INSERT INTO scm.repository_master_event (tenant_id, repository_id, repository_version, action, actor_id, correlation_id, after_state) VALUES (NEW.tenant_id, NEW.repository_id, NEW.version, CASE WHEN NEW.version = 1 THEN 'created' ELSE 'revised' END, current_actor, current_correlation, jsonb_build_object('name', NEW.name, 'provider_key', NEW.provider_key, 'remote_identity', NEW.remote_identity, 'remote_url', NEW.remote_url, 'default_branch', NEW.default_branch, 'created_by_actor_id', NEW.created_by_actor_id, 'changed_by_actor_id', NEW.changed_by_actor_id, 'version', NEW.version)); RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION scm.guard_repository_master_event() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, scm AS $function$ BEGIN RAISE EXCEPTION 'SCM Repository master audit is append-only'; END $function$;
DROP TRIGGER IF EXISTS repository_master_revision_guard ON scm.repository_master;
CREATE TRIGGER repository_master_revision_guard BEFORE INSERT OR UPDATE OR DELETE ON scm.repository_master FOR EACH ROW EXECUTE FUNCTION scm.guard_repository_master_revision();
DROP TRIGGER IF EXISTS repository_master_current_revision_check ON scm.repository_master;
CREATE CONSTRAINT TRIGGER repository_master_current_revision_check AFTER INSERT OR UPDATE ON scm.repository_master DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION scm.assert_repository_master_current_revision();
DROP TRIGGER IF EXISTS repository_master_revision_audit ON scm.repository_master;
CREATE TRIGGER repository_master_revision_audit AFTER INSERT ON scm.repository_master FOR EACH ROW EXECUTE FUNCTION scm.audit_repository_master_revision();
DROP TRIGGER IF EXISTS repository_master_event_worm ON scm.repository_master_event;
CREATE TRIGGER repository_master_event_worm BEFORE UPDATE OR DELETE ON scm.repository_master_event FOR EACH ROW EXECUTE FUNCTION scm.guard_repository_master_event();
DROP TRIGGER IF EXISTS repository_master_event_no_truncate ON scm.repository_master_event;
